package io.github.phiscript.assets;import android.content.Context;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import io.github.phiscript.engine.Chart;import io.github.phiscript.vision.*;import io.github.phiscript.capture.CourseEngineRegression;public class SessionChartSource {public static SessionChartSource phigros(Context c,ChartLibrary l,AtomicBoolean stop){return new SessionChartSource();}public List<PhiraEntry> getEntries(){List<PhiraEntry> entries=new ArrayList<>();for(int i=1;i<=3;i++)entries.add(new PhiraEntry("song"+i,"Song "+i,"IN",Collections.emptyList(),16.0/9,false));return entries;}public PhiraCandidate match(OcrLabels labels,List<PhiraCandidate> candidates){if(CourseEngineRegression.scenario.equals("ambiguous"))return null;int stage=CourseEngineRegression.plays;return candidates.get(Math.min(2,stage));}public Chart load(String id,String level){CourseEngineRegression.loads++;return new Chart();}}
